mapper.select:
SELECT 
FROM department d
LEFT JOIN workplace w ON w.id = d.workplace_id
WHERE d.tenant_id = #{tenantId}
  AND d.id = #{id}

SELECT 
FROM department d
LEFT JOIN workplace w ON w.id = d.workplace_id
WHERE d.tenant_id = #{tenantId}
  AND d.department_code = #{departmentCode}

mapper.insert:
INSERT INTO department (
  tenant_id, workplace_id, parent_id, department_code, department_name, sort_order, status
) VALUES (
  #{tenantId}, #{in.workplaceId}, #{in.parentId}, #{in.departmentCode}, #{in.departmentName}, #{in.sortOrder}, #{in.status}
)

mapper.delete:
DELETE FROM department
WHERE tenant_id = #{tenantId}
  AND id = #{id}

mapper.select:
SELECT COUNT(*)
FROM employee
WHERE tenant_id = #{tenantId}
  AND department_id = #{departmentId}
